import { type Page, type Locator } from '@playwright/test';

export class EnterprisePageObject {
  readonly page: Page;

  readonly usernameInput: Locator;
  readonly passwordInput: Locator;
  readonly submitButton: Locator;
  readonly cancelButton: Locator;
  readonly resetButton: Locator;
  readonly loadingSpinner: Locator;
  readonly errorMessage: Locator;
  readonly successMessage: Locator;
  readonly modal: Locator;
  readonly modalClose: Locator;
  readonly modalTitle: Locator;
  readonly modalContent: Locator;
  readonly sidebar: Locator;
  readonly sidebarItem: Locator;
  readonly header: Locator;
  readonly footer: Locator;
  readonly navigation: Locator;
  readonly breadcrumbs: Locator;
  readonly tabs: Locator;
  readonly tabPanel: Locator;
  readonly searchInput: Locator;
  readonly searchResults: Locator;
  readonly filterDropdown: Locator;
  readonly sortDropdown: Locator;
  readonly pagination: Locator;
  readonly table: Locator;
  readonly tableRow: Locator;
  readonly tableCell: Locator;
  readonly tableHeader: Locator;
  readonly checkBox: Locator;
  readonly radioButton: Locator;
  readonly selectDropdown: Locator;
  readonly multiSelect: Locator;
  readonly datePicker: Locator;
  readonly dateInput: Locator;
  readonly timePicker: Locator;
  readonly slider: Locator;
  readonly progressBar: Locator;
  readonly toast: Locator;
  readonly alert: Locator;
  readonly tooltip: Locator;
  readonly popover: Locator;
  readonly dropdown: Locator;
  readonly dropdownItem: Locator;
  readonly menu: Locator;
  readonly menuItem: Locator;
  readonly list: Locator;
  readonly listItem: Locator;
  readonly card: Locator;
  readonly cardTitle: Locator;
  readonly cardContent: Locator;
  readonly cardFooter: Locator;
  readonly avatar: Locator;
  readonly badge: Locator;
  readonly label: Locator;
  readonly inputGroup: Locator;
  readonly form: Locator;
  readonly fieldSet: Locator;
  readonly legend: Locator;
  readonly helpText: Locator;
  readonly validationError: Locator;
  readonly confirmationDialog: Locator;
  readonly actionButton: Locator;
  readonly primaryButton: Locator;
  readonly secondaryButton: Locator;
  readonly dangerButton: Locator;
  readonly link: Locator;
  readonly icon: Locator;
  readonly image: Locator;
  readonly video: Locator;
  readonly audio: Locator;
  readonly loader: Locator;
  readonly skeleton: Locator;
  readonly emptyState: Locator;
  readonly loadingState: Locator;
  readonly errorState: Locator;
  readonly successState: Locator;
  readonly warningState: Locator;
  readonly infoState: Locator;
  readonly section: Locator;
  readonly article: Locator;
  readonly aside: Locator;
  readonly main: Locator;

  constructor(page: Page) {
    this.page = page;
    this.usernameInput = page.locator('#username, input[name="username"], [data-testid="username"]');
    this.passwordInput = page.locator('#password, input[name="password"]');
    this.submitButton = page.locator('button[type="submit"], .btn-submit, [data-testid="submit"]');
    this.cancelButton = page.locator('button[type="cancel"], .btn-cancel');
    this.resetButton = page.locator('button[type="reset"], .btn-reset');
    this.loadingSpinner = page.locator('.spinner, .loading, [data-testid="loading"]');
    this.errorMessage = page.locator('.error, .error-message, [data-testid="error"]');
    this.successMessage = page.locator('.success, .success-message, [data-testid="success"]');
    this.modal = page.locator('.modal, [role="dialog"]');
    this.modalClose = page.locator('.modal .close, [aria-label="Close"]');
    this.modalTitle = page.locator('.modal-title, [role="heading"]');
    this.modalContent = page.locator('.modal-content');
    this.sidebar = page.locator('.sidebar, [data-testid="sidebar"]');
    this.sidebarItem = page.locator('.sidebar-item, .sidebar a');
    this.header = page.locator('header, .header, [data-testid="header"]');
    this.footer = page.locator('footer, .footer');
    this.navigation = page.locator('nav, .nav, [data-testid="navigation"]');
    this.breadcrumbs = page.locator('.breadcrumbs, [aria-label="Breadcrumb"]');
    this.tabs = page.locator('.tabs, [role="tablist"]');
    this.tabPanel = page.locator('.tab-panel, [role="tabpanel"]');
    this.searchInput = page.locator('input[type="search"], input[name="q"]');
    this.searchResults = page.locator('.search-results, .results');
    this.filterDropdown = page.locator('.filter, [data-testid="filter"]');
    this.sortDropdown = page.locator('.sort, [data-testid="sort"]');
    this.pagination = page.locator('.pagination, [data-testid="pagination"]');
    this.table = page.locator('table, .table');
    this.tableRow = page.locator('tr, .table-row');
    this.tableCell = page.locator('td, .cell');
    this.tableHeader = page.locator('th, .header-cell');
    this.checkBox = page.locator('input[type="checkbox"]');
    this.radioButton = page.locator('input[type="radio"]');
    this.selectDropdown = page.locator('select');
    this.multiSelect = page.locator('select[multiple]');
    this.datePicker = page.locator('.datepicker, input[type="date"]');
    this.dateInput = page.locator('input[type="date"]');
    this.timePicker = page.locator('.timepicker, input[type="time"]');
    this.slider = page.locator('input[type="range"]');
    this.progressBar = page.locator('.progress, .progress-bar');
    this.toast = page.locator('.toast, [data-testid="toast"]');
    this.alert = page.locator('.alert, [role="alert"]');
    this.tooltip = page.locator('.tooltip, [data-tooltip]');
    this.popover = page.locator('.popover');
    this.dropdown = page.locator('.dropdown, [data-dropdown]');
    this.dropdownItem = page.locator('.dropdown-item');
    this.menu = page.locator('.menu, [role="menu"]');
    this.menuItem = page.locator('.menu-item, [role="menuitem"]');
    this.list = page.locator('ul, ol, .list');
    this.listItem = page.locator('li, .list-item');
    this.card = page.locator('.card, [data-testid="card"]');
    this.cardTitle = page.locator('.card-title, .card h2');
    this.cardContent = page.locator('.card-content');
    this.cardFooter = page.locator('.card-footer');
    this.avatar = page.locator('.avatar, [data-testid="avatar"]');
    this.badge = page.locator('.badge, [data-testid="badge"]');
    this.label = page.locator('label');
    this.inputGroup = page.locator('.input-group');
    this.form = page.locator('form');
    this.fieldSet = page.locator('fieldset');
    this.legend = page.locator('legend');
    this.helpText = page.locator('.help-text, .hint');
    this.validationError = page.locator('.field-error, .validation-error');
    this.confirmationDialog = page.locator('.confirmation, [data-testid="confirm"]');
    this.actionButton = page.locator('button.action, .btn-action');
    this.primaryButton = page.locator('.btn-primary, button.primary');
    this.secondaryButton = page.locator('.btn-secondary');
    this.dangerButton = page.locator('.btn-danger, .btn-danger');
    this.link = page.locator('a');
    this.icon = page.locator('.icon, [data-icon]');
    this.image = page.locator('img');
    this.video = page.locator('video');
    this.audio = page.locator('audio');
    this.loader = page.locator('.loader, [data-testid="loader"]');
    this.skeleton = page.locator('.skeleton, .loading-skeleton');
    this.emptyState = page.locator('.empty-state, [data-testid="empty"]');
    this.loadingState = page.locator('.loading-state');
    this.errorState = page.locator('.error-state');
    this.successState = page.locator('.success-state');
    this.warningState = page.locator('.warning-state');
    this.infoState = page.locator('.info-state');
    this.section = page.locator('section');
    this.article = page.locator('article');
    this.aside = page.locator('aside');
    this.main = page.locator('main');
  }

  async login(username: string, password: string) {
    await this.usernameInput.fill(username);
    await this.passwordInput.fill(password);
    await this.submitButton.click();
  }

  async waitForLoading() {
    await this.loadingSpinner.waitFor({ state: 'hidden' });
  }

  async getErrorMessage(): Promise<string> {
    return this.errorMessage.textContent() ?? '';
  }
}